                nullptr,
                0.088388347648f  // 1/sqrt(128)
            );

        cg::this_grid().sync();
        A = A_had;
    }

    int size_m_ = size_m;
    const half* A_ = A;
    void* C_ = C;

    while (size_m_ > 0)
